export class AnimationClip {
    constructor(target, update) {
        this.target = target;
        this.updateFunc = update;
    }
    Update() {
        this.updateFunc(this.target);
    }
}
export class Animator {
    constructor() {
        this.name = "animator";
        this.clips = [];
        this.current = null;
        this.currentIndex = -1;
        this.owner = null;
    }
    AddClip(update) {
        if (!this.owner)
            return;
        this.clips.push(new AnimationClip(this.owner, update));
    }
    Next() {
        this.currentIndex++;
        if (this.currentIndex >= 0 && this.currentIndex < this.clips.length) {
            this.current = this.clips[this.currentIndex];
        }
    }
    OnStart() {
    }
    OnUpdate() {
        if (this.current) {
            this.current.Update();
        }
    }
    BeforeRemove() {
    }
}
